const rows = $input.all().map((item) => item.json || {});
const MAX_UPSTREAM_ITEMS = 500;
const urlSet = new Set();
const upstreamItems = [];
let agencyPreset = 'auto_best_fit';
let dedupStoreName = '';
let dedupMode = 'watch_diff';

for (const row of rows) {
  if (Array.isArray(row.upstreamItems)) {
    for (const item of row.upstreamItems) {
      if (upstreamItems.length >= MAX_UPSTREAM_ITEMS) break;
      if (item && typeof item === 'object') upstreamItems.push(item);
    }
  } else if (typeof row.upstreamItems === 'string' && row.upstreamItems.trim().startsWith('[')) {
    try {
      const parsed = JSON.parse(row.upstreamItems);
      if (Array.isArray(parsed)) {
        for (const item of parsed) {
          if (upstreamItems.length >= MAX_UPSTREAM_ITEMS) break;
          if (item && typeof item === 'object') upstreamItems.push(item);
        }
      }
    } catch {}
  }
  if ((row.snapshot || row.adSnapshot || row.pageId || row.pageName || row.advertiserName || row.link_url || row.linkUrl) && upstreamItems.length < MAX_UPSTREAM_ITEMS) {
    upstreamItems.push(row);
  }
  const u = row.landingPageUrl || row.websiteUrl || row.url || row.domain || '';
  if (typeof u === 'string' && u.trim() && urlSet.size < MAX_UPSTREAM_ITEMS) urlSet.add(u.trim());
  if (typeof row.agencyPreset === 'string' && row.agencyPreset.trim()) {
    agencyPreset = row.agencyPreset.trim();
  }
  if (!dedupStoreName && typeof row.dedupStoreName === 'string' && row.dedupStoreName.trim()) {
    dedupStoreName = row.dedupStoreName.trim();
  }
  if (typeof row.dedupMode === 'string' && (row.dedupMode === 'skip_seen' || row.dedupMode === 'watch_diff')) {
    dedupMode = row.dedupMode;
  }
}

const landingPageUrls = Array.from(urlSet);
const payload = {
  agencyPreset,
  crmExportPreset: 'default',
  enableContactPageFollow: true,
  enableDnsEmailCheck: true,
  enableStorefrontCatalogAudit: true,
  onlyWithEmail: false,
  onlyWithActiveLeaks: false,
  maxBrands: 50,
  maxConcurrency: 3
};
if (upstreamItems.length > 0) {
  payload.upstreamItems = upstreamItems.slice(0, MAX_UPSTREAM_ITEMS);
}
if (landingPageUrls.length > 0) {
  payload.landingPageUrls = landingPageUrls;
} else if (upstreamItems.length === 0) {
  payload.landingPageUrls = ['https://www.chomps.com/', 'https://www.brooklinen.com/products/discontinued-summer-promo-demo-404'];
}
if (dedupStoreName) {
  payload.dedupStoreName = dedupStoreName;
  payload.dedupMode = dedupMode;
}

return [{ json: payload }];

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json || {};
  const priority = d.hasNewBuyingTrigger ? 'VIP_HOT' : (d.leadPriority || 'NURTURE');
  const triggers = Array.isArray(d.changeTriggers) && d.changeTriggers.length > 0 ? d.changeTriggers.join(', ') : 'None';
  const angle = d.detectedLeaksSummary || d.expansionOpportunitiesCsv || d.recommendedAgencyAngle || 'General Audit';

  const slackSummary = [
    `:dart: *[${priority}] DTC Advertiser Lead:* ${d.brandName} (${d.brandDomain}) — *${d.buyerFitTier || 'Unknown'}*`,
    `*Scores:* Leak ${d.leakScore ?? 0}/100 | Expansion ${d.expansionScore ?? 0}/100 | Deliverability: *${d.deliverabilityGrade || 'N/A'}* | Stack: ${d.techStackCount ?? 0} tools`,
    `*Contact:* ${d.primaryEmail || 'No email'} (${d.inboxType || 'unknown'}) | *Exec:* ${d.executiveName || 'DM Search'} ${d.linkedinDecisionMakerSearchUrl || ''}`,
    `*Signal / Angle:* ${angle}`,
    `*Watch-Diff Triggers:* ${triggers}`,
    `*Subject:* ${d.coldEmailSubject || d.subjectLine || ''}`,
    `*Opener:* ${d.coldEmailOpener || ''}`
  ].join('\n');

  results.push({
    json: {
      ...d,
      effectivePriority: priority,
      triggersText: triggers,
      slackSummary
    }
  });
}

return results;
